// Private media grant: same employee identity, short lived, HttpOnly and no URL token.
const KB_COOKIE='__Secure-cplink_kb',KB_PATH='/api/knowledge/',KB_LIMIT=1048576;
class KnowledgeError extends Error{constructor(message,status=503){super(message);this.status=status}}
const kbJSON=(value,status=200,extra={})=>Response.json(value,{status,headers:{'Cache-Control':'no-store, private','X-Content-Type-Options':'nosniff',...extra}});
const kbBase=b=>btoa(String.fromCharCode(...b)).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'');
const kbBytes=s=>Uint8Array.from(atob(s.replaceAll('-','+').replaceAll('_','/')),x=>x.charCodeAt(0));
async function kbKey(env){if(!/^[a-f0-9]{64}$/i.test(env.CABINET_SIGNING_KEY||''))throw new KnowledgeError('Доступ к файлам ещё запускается');return crypto.subtle.importKey('raw',Uint8Array.from(env.CABINET_SIGNING_KEY.match(/../g),x=>parseInt(x,16)),{name:'HMAC',hash:'SHA-256'},false,['sign','verify'])}
async function kbSeal(t,env){const at=Math.floor(Date.now()/1000),d=kbBase(new TextEncoder().encode(JSON.stringify({uid:t.uid,employee_id:Number(t.employee_id),iat:at,exp:Math.min(t.exp,at+600)})));return d+'.'+kbBase(new Uint8Array(await crypto.subtle.sign('HMAC',await kbKey(env),new TextEncoder().encode('knowledge-v1:'+d))))}
async function kbIdentity(request,env){
 const at=Math.floor(Date.now()/1000),existing=env.BROWSER_IDENTITY;if(existing&&existing.exp>at)return existing;
 try{const value=(request.headers.get('cookie')||'').split(';').map(x=>x.trim()).find(x=>x.startsWith(KB_COOKIE+'='))?.slice(KB_COOKIE.length+1);if(!value||value.length>1024)return null;const [d,s,...rest]=value.split('.');if(rest.length||!s||!await crypto.subtle.verify('HMAC',await kbKey(env),kbBytes(s),new TextEncoder().encode('knowledge-v1:'+d)))return null;const t=JSON.parse(new TextDecoder().decode(kbBytes(d)));return Number.isSafeInteger(t.uid)&&t.uid>0&&Number.isSafeInteger(t.employee_id)&&t.employee_id>0&&Number.isSafeInteger(t.iat)&&Number.isSafeInteger(t.exp)&&t.iat<=at+30&&t.exp>at&&t.exp-t.iat<=600?t:null}catch{return null}
}
async function kbSource(env,t,asset,start,limit){
 if(typeof env.PRODUCTION_FETCH!=='function')throw new KnowledgeError('Сервер файлов недоступен');
 const url=new URL('https://productionwages.axiomalink.ru/api/v1/cabinet/'+(asset?'knowledge-media':'identity'));url.searchParams.set('telegram_id',String(t.uid));if(asset)url.searchParams.set('employee_id',String(t.employee_id));
 if(asset)for(const[k,v]of Object.entries({asset,offset:start,limit}))url.searchParams.set(k,String(v));
 const r=await env.PRODUCTION_FETCH(url),d=await r.json();if([403,422].includes(r.status))throw new KnowledgeError(d.error||'Материал недоступен',r.status);
 if(!r.ok||d.source!=='employee-cabinet-local'||d.telegram_id!==t.uid||String(d.employee_id)!==String(t.employee_id))throw new KnowledgeError('Не удалось проверить доступ к файлу');
 if(!asset)return d;
 if(d.asset!==asset||!Number.isSafeInteger(d.size)||d.size<1||d.size>80*1048576)throw new KnowledgeError('Не удалось проверить файл');
 if(d.range_error)return d;
 if(d.start!==start||!Number.isSafeInteger(d.end)||d.end<start||d.end>=d.size||d.end-start+1>limit||typeof d.data!=='string'||d.data.length>1400000||!/^[A-Za-z0-9+/]*={0,2}$/.test(d.data))throw new KnowledgeError('Файл получен не полностью');
 const bytes=Uint8Array.from(atob(d.data),x=>x.charCodeAt(0));if(bytes.length!==d.end-start+1)throw new KnowledgeError('Файл получен не полностью');return {...d,bytes};
}
async function knowledgeAPI(request,env,authorize){
 const url=new URL(request.url);if(!['/api/knowledge/session','/api/knowledge/media'].includes(url.pathname))return null;
 try{
  if(request.headers.get('Origin')&&request.headers.get('Origin')!==url.origin||request.headers.get('Sec-Fetch-Site')==='cross-site')throw new KnowledgeError('Запрос отклонён',403);
  if(url.pathname.endsWith('/session')){
   if(request.method!=='POST')throw new KnowledgeError('Используйте POST',405);
   if(request.headers.get('Origin')!==url.origin||!request.headers.get('Content-Type')?.startsWith('application/json'))throw new KnowledgeError('Запрос отклонён',403);
   const raw=await request.text();if(raw.length>20000)throw new KnowledgeError('Запрос слишком большой',413);
   let t;try{t=await authorize(JSON.parse(raw),env)}catch{throw new KnowledgeError('Войдите в личный кабинет',401)}
   await kbSource(env,t);const grant=await kbSeal(t,env);return kbJSON({ok:true,expires_at:Math.min(t.exp,Math.floor(Date.now()/1000)+600)},200,{'Set-Cookie':KB_COOKIE+'='+grant+'; Path='+KB_PATH+'; Max-Age=600; HttpOnly; Secure; SameSite=Strict'});
  }
  if(!['GET','HEAD'].includes(request.method))throw new KnowledgeError('Используйте GET',405);
  const t=await kbIdentity(request,env);if(!t)throw new KnowledgeError('Войдите в личный кабинет',401);
  const asset=url.searchParams.get('asset');if(!/^[a-f0-9]{32}$/.test(asset||'')||[...url.searchParams.keys()].some(k=>k!=='asset')||url.searchParams.getAll('asset').length!==1)throw new KnowledgeError('Некорректный файл',422);
  const rawRange=request.headers.get('Range'),range=rawRange?.match(/^bytes=(\d*)-(\d*)$/);
  if(rawRange&&(!range||!range[1]&&!range[2]))throw new KnowledgeError('Некорректная часть файла',416);
  let start=range?.[1]?Number(range[1]):0,initialLimit=range?.[1]&&range[2]?Math.min(KB_LIMIT,Number(range[2])-start+1):KB_LIMIT;
  if(range&&!range[1])initialLimit=1;
  if(!Number.isSafeInteger(start)||start<0||initialLimit<1)throw new KnowledgeError('Некорректная часть файла',416);
  let first=await kbSource(env,t,asset,start,initialLimit),size=first.size;
  if(range&&!range[1])start=Math.max(0,size-Number(range[2]));
  const end=range?.[1]&&range[2]?Math.min(size-1,Number(range[2])):size-1;
  if(first.range_error||!Number.isSafeInteger(start)||!Number.isSafeInteger(end)||start> end||start>=size)return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+size,'Cache-Control':'no-store, private'}});
  if(first.start!==start||first.end>end)first=await kbSource(env,t,asset,start,Math.min(KB_LIMIT,end-start+1));
  const mime=/^(image\/(jpeg|png|webp|gif)|video\/(mp4|webm|quicktime|x-msvideo|x-ms-wmv))$/.test(first.mime||'')?first.mime:'application/octet-stream';
  const headers={'Content-Type':mime,'Content-Length':String(end-start+1),'Accept-Ranges':'bytes','Cache-Control':'no-store, private','Vary':'Cookie','X-Content-Type-Options':'nosniff','Content-Disposition':(first.kind==='file'?'attachment':'inline')+"; filename*=UTF-8''"+encodeURIComponent(String(first.filename||'material').slice(0,220))};if(range)headers['Content-Range']='bytes '+start+'-'+end+'/'+size;
  let next=start,part=first,cancelled=false;
  const body=request.method==='HEAD'?null:new ReadableStream({async pull(controller){try{if(cancelled)return;if(next>end){controller.close();return}const d=part||await kbSource(env,t,asset,next,Math.min(KB_LIMIT,end-next+1));part=null;if(d.range_error||d.start!==next||d.size!==size)throw new KnowledgeError('Файл изменился во время просмотра');controller.enqueue(d.bytes);next=d.end+1;if(next>end)controller.close()}catch(e){controller.error(e)}},cancel(){cancelled=true}});
  return new Response(body,{status:range?206:200,headers});
 }catch(e){return kbJSON({error:e instanceof KnowledgeError?e.message:'Файл временно недоступен'},e instanceof KnowledgeError?e.status:503)}
}

// Fixed city forecast only. No browser IP, employee identity or geolocation is forwarded.
function createWeatherProvider(fetcher=fetch,clock=()=>Date.now()){
 let forecast=null,nextFetch=0,lastModified='',pending=null,retrieved=0,failed=false;
 function result(stale=false){
  const now=clock(),rows=forecast?.properties?.timeseries||[],updated=Date.parse(forecast?.properties?.meta?.updated_at);
  const row=rows.reduce((best,r)=>!best||Math.abs(Date.parse(r.time)-now)<Math.abs(Date.parse(best.time)-now)?r:best,null);
  const temperature=row?.data?.instant?.details?.air_temperature;
  const symbol=(row?.data?.next_1_hours||row?.data?.next_6_hours||row?.data?.next_12_hours)?.summary?.symbol_code;
  const available=Number.isFinite(temperature)&&typeof symbol==='string'&&/^[a-z_]{1,80}$/.test(symbol)&&Number.isFinite(updated)&&now-updated<24*3600000&&updated<=now+3600000&&Math.abs(Date.parse(row?.time)-now)<=3*3600000&&now-retrieved<=6*3600000;
  return {city:'Казань',available,...(available?{temperature,symbol,valid_at:row.time,updated_at:new Date(updated).toISOString(),retrieved_at:new Date(retrieved).toISOString(),stale}:{}),source:'MET Norway',license:'CC BY 4.0',basis:'forecast'};
 }
 return async function getWeather(){
  if(clock()<nextFetch)return result(failed);
  if(pending)return pending;
  pending=(async()=>{try{
   const response=await fetcher('https://api.met.no/weatherapi/locationforecast/2.0/compact?lat=55.79&lon=49.12',{headers:{'User-Agent':'CplinkCabinet/1.0 https://github.com/radif4ik/cplink-scan','Accept':'application/json',...(lastModified?{'If-Modified-Since':lastModified}:{})},signal:AbortSignal.timeout(8000)});
   if(response.status!==304){if(!response.ok)throw Error('weather');const body=await response.json();if(!Array.isArray(body?.properties?.timeseries)||!body.properties.timeseries.length)throw Error('schema');forecast=body;lastModified=response.headers.get('last-modified')||'';retrieved=clock()}
   const expires=Date.parse(response.headers.get('expires'));
   nextFetch=Math.max(clock()+30*60000,Number.isFinite(expires)?expires:0);
   failed=false;return result();
  }catch{failed=true;nextFetch=clock()+30*60000;return result(true)}finally{pending=null}})();
  return pending;
 };
}

