  if(u.pathname==='/' && request.method==='GET')return new Response(PAGE,{headers:{...headers,'Content-Type':'text/html; charset=utf-8','Content-Security-Policy':"default-src 'self'; script-src 'self' 'unsafe-inline' https://telegram.org https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; media-src 'self' blob:; connect-src 'self'; frame-src https://oauth.telegram.org; frame-ancestors 'self' https://web.telegram.org https://*.telegram.org; base-uri 'none'; form-action 'none'"}});
  if(!['/api/cabinet','/api/history','/api/score','/api/orders','/api/order',...Object.keys(actionRoutes),...Object.keys(workspaceRoutes)].includes(u.pathname))return json({error:'Страница не найдена'},404);
